import json

VALID_SEARCH_MODES = {"quick", "deep", "research"}
MAX_MARKDOWN_SOURCES = 10


def _require_results(value):
    if not isinstance(value, list):
        raise TypeError("public_search prompt: search_results must be array")
    return value


def _result_text(item, key, index):
    value = item[key]
    if not isinstance(value, str):
        raise TypeError(f"public_search prompt: search_results[{index}].{key} must be string")
    text = value.strip()
    if text == "":
        raise ValueError(f"public_search prompt: search_results[{index}].{key} must be non-empty")
    return text


def _markdown_label(text):
    return " ".join(text.replace("[", "(").replace("]", ")").split())


def _markdown_url(url):
    return url.replace(" ", "%20").replace("(", "%28").replace(")", "%29")


def _source_host(url):
    rest = url
    marker = "://"
    if marker in rest:
        rest = rest.split(marker, 1)[1]
    host = rest.split("/", 1)[0].split("?", 1)[0].split("#", 1)[0].lower()
    if "@" in host:
        host = host.rsplit("@", 1)[1]
    if host.startswith("www."):
        host = host[4:]
    return host


def _markdown_sources(results):
    lines = []
    for index, item in enumerate(results[:MAX_MARKDOWN_SOURCES], start=1):
        if not isinstance(item, dict):
            raise TypeError(f"public_search prompt: search_results[{index}] must be object")
        title = _result_text(item, "title", index)
        url = _result_text(item, "url", index)
        provider = _result_text(item, "provider", index)
        host = _source_host(url)
        meta = provider if host == "" else f"{provider}, {host}"
        lines.append(f"{index}. [{_markdown_label(title)}]({_markdown_url(url)}) — {meta}")
    if not lines:
        return "Источники отсутствуют."
    return "\n".join(lines)


async def run(args, state):
    raw_variables = state["variables"]
    if not isinstance(raw_variables, dict):
        raise TypeError("public_search prompt: state.variables must be object")
    variables = dict(raw_variables)
    mode = variables["search_mode"]
    if mode not in VALID_SEARCH_MODES:
        raise ValueError("public_search prompt: variables.search_mode is invalid")

    search_results = _require_results(state["search_results"])
    markdown_sources = _markdown_sources(search_results)
    variables["search_query"] = state["search_user_query"]
    variables["search_effective_query"] = state["search_effective_query"]
    variables["search_file_context"] = state["search_file_context"]
    variables["search_results"] = json.dumps(search_results, ensure_ascii=False, indent=2)
    variables["search_markdown_sources"] = markdown_sources
    variables["search_providers_status"] = json.dumps(state["search_providers_status"], ensure_ascii=False, indent=2)
    variables["search_suggestions"] = json.dumps(state["search_suggestions"], ensure_ascii=False, indent=2)
    variables["search_followups"] = json.dumps(state["search_followups"], ensure_ascii=False, indent=2)
    variables["search_result_insights"] = json.dumps(state["search_result_insights"], ensure_ascii=False, indent=2)
    return {"search_markdown_sources": markdown_sources, "variables": variables}

search_answer.prompt:
Ты — поисковый агент Humanitec.

Search MCP уже выполнил первичный web search, подсказки и per-result insights. Используй только данные ниже.

Режим поиска:
{search_mode}

Исходный запрос пользователя:
{search_query}

Краткий контекст приложенных файлов, если они были:
{search_file_context}

Фактический поисковый запрос для провайдеров:
{search_effective_query}

Нормализованная выдача:
{search_results}

Markdown-источники для финального ответа:
{search_markdown_sources}

Статусы провайдеров:
{search_providers_status}

Подсказки для уточнения:
{search_suggestions}

Follow-up вопросы:
{search_followups}

Инсайты по результатам:
{search_result_insights}

Правила:
1) Если search_results пустой — честно скажи, что первичная выдача сейчас недоступна. Если в search_providers_status есть error, кратко укажи его.
2) Если результаты есть — дай короткий ответ по title/snippet результатов и учитывай search_file_context как контекст запроса, а не как внешний источник. При каждом фактическом утверждении ставь инлайн-цитату вида [N], где N — порядковый номер источника из блока «Markdown-источники» (он совпадает с порядком в search_results). Разрешены только номера реально существующих источников; для нескольких источников подряд пиши [1][2].
3) Не вызывай read_file повторно: приложенные файлы уже прочитаны и кратко суммаризированы до web search.
4) create_file используй только по явной просьбе сформировать отчет, таблицу, PDF, Markdown или другой файл.
5) В конце добавь раздел «Источники» и вставь туда Markdown-источники из блока выше. Не выводи raw URL отдельным текстом: URL допустим только внутри Markdown-ссылки вида [название](url).
6) После источников добавь 2-3 «Что уточнить дальше» на основе search_followups.
7) Не утверждай, что ты прочитал страницы целиком: на этом этапе доступна первичная выдача, поисковые инсайты и краткий контекст файлов.

