import asyncio

TRACKING_KEYS = {'fbclid', 'gclid', 'yclid', 'ref', 'ref_src'}


def _canonical_url(url):
    u = url.strip()
    if '://' in u:
        _, rest = u.split('://', 1)
    else:
        rest = u
    rest = rest.split('#', 1)[0]
    if '?' in rest:
        path, query = rest.split('?', 1)
    else:
        path, query = rest, ''
    path = path.lower()
    if path.endswith('/') and len(path) > 1:
        path = path.rstrip('/')
    kept = []
    for pair in query.split('&'):
        if pair == '':
            continue
        key = pair.split('=', 1)[0].lower()
        if key in TRACKING_KEYS or key.startswith('utm_'):
            continue
        kept.append(pair)
    if kept:
        return path + '?' + '&'.join(sorted(kept))
    return path


async def _search_one(query, limit, providers, strategy, language, region):
    raw = await tools.web_search(
        query=query,
        limit=limit,
        providers=providers,
        provider_strategy=strategy,
        language=language,
        region=region,
        mode='research',
    )
    if raw.get('success') is not True:
        return {'query': query, 'results': [], 'error': str(raw.get('error', 'web_search failed'))}
    results = raw.get('results')
    if not isinstance(results, list):
        return {'query': query, 'results': [], 'error': 'web_search: results is not a list'}
    return {'query': query, 'results': results, 'error': ''}


async def run(args, state):
    if state.get('research_continue') is False:
        return {'research_candidates': []}
    pending = state.get('research_pending_queries')
    if not isinstance(pending, list):
        raise TypeError('research search: research_pending_queries must be array')
    queries = []
    for item in pending:
        s = str(item).strip()
        if s != '':
            queries.append(s)
    if len(queries) == 0:
        return {'research_candidates': []}
    variables = state['variables']
    limit = int(variables.get('research_search_limit_per_query', 8))
    strategy = variables.get('search_provider_strategy', 'merge')
    providers = variables.get('search_providers', ['auto'])
    language = variables.get('search_language', 'ru')
    region = variables.get('search_region', 'ru')
    outcomes = await asyncio.gather(*[
        _search_one(q, limit, providers, strategy, language, region) for q in queries
    ])
    seen = state.get('research_seen_urls')
    seen_set = set(seen) if isinstance(seen, list) else set()
    scores = {}
    candidates = {}
    for outcome in outcomes:
        for item in outcome['results']:
            if not isinstance(item, dict):
                continue
            url = str(item.get('url', '')).strip()
            title = str(item.get('title', '')).strip()
            if url == '' or title == '':
                continue
            key = _canonical_url(url)
            if key == '' or key in seen_set:
                continue
            rank = item.get('provider_rank')
            rank_val = rank if isinstance(rank, int) and rank >= 1 else 50
            score = 1.0 / (60.0 + float(rank_val))
            if key not in candidates:
                provider = str(item.get('provider', '')).strip()
                if provider == '':
                    provider = 'web'
                candidates[key] = {
                    'url': url,
                    'title': title,
                    'snippet': str(item.get('snippet', '')).strip(),
                    'provider': provider,
                    'site_name': str(item.get('site_name', '')).strip(),
                }
                scores[key] = score
            else:
                scores[key] += score
    ranked_keys = sorted(candidates.keys(), key=lambda k: -scores[k])
    ranked = [candidates[k] for k in ranked_keys]
    query_stats = [
        {'query': o['query'], 'count': len(o['results']), 'error': o['error']}
        for o in outcomes
    ]
    await capability(
        'state.push_ui_event',
        event_type='search/research/search_ready',
        payload={
            'kind': 'public_search_research_update',
            'version': 1,
            'flow_id': 'public_search',
            'phase': 'search',
            'mode': 'research',
            'query': state.get('research_query'),
            'iteration': int(state.get('research_iteration', 0)),
            'queries': query_stats,
            'found': len(ranked),
            'candidates': [
                {'url': c['url'], 'title': c['title'], 'provider': c['provider'], 'site_name': c['site_name']}
                for c in ranked[:12]
            ],
        },
        source='public_search',
    )
    return {'research_candidates': ranked}

