MAX_SOURCES = 8


def _md_label(text):
    return ' '.join(text.replace('[', '(').replace(']', ')').split())


async def run(args, state):
    variables = dict(state['variables'])
    sources = state.get('research_sources')
    if not isinstance(sources, list):
        sources = []
    lines = []
    blocks = []
    for src in sources[:MAX_SOURCES]:
        index = src['index']
        title = src['title']
        url = src['url']
        provider = src['provider']
        lines.append(str(index) + '. [' + _md_label(title) + '](' + url + ') — ' + provider)
        blocks.append('[Источник ' + str(index) + '] ' + title + ' (' + url + ')\n' + src['content'])
    if lines:
        markdown_sources = '\n'.join(lines)
    else:
        markdown_sources = 'Источники отсутствуют.'
    if blocks:
        context = '\n\n---\n\n'.join(blocks)
    else:
        context = 'Нет прочитанных источников.'
    outline = state.get('research_outline')
    if isinstance(outline, list) and outline:
        outline_text = '\n'.join('- ' + o for o in outline)
    else:
        outline_text = '- (план разделов не задан)'
    coverage = state.get('research_coverage_note')
    if not isinstance(coverage, str):
        coverage = ''
    brief = state.get('research_brief')
    if not isinstance(brief, str):
        brief = ''
    variables['research_query'] = state.get('research_query')
    variables['research_brief'] = brief
    variables['research_outline_text'] = outline_text
    variables['research_markdown_sources'] = markdown_sources
